public static class AV2Generator {
 const string Root="Assets/AyutthayaShophouseV2";
 [Serializable] class Fragment { public string name; public float[] pos; }
 [Serializable] class Entry { public string name,kind,collider,glass,pair;public float[] pos; public float rotation,angle,hp;public int group,triangles;public bool support;public Fragment[] fragments; }
 [Serializable] class Manifest { public Entry[] modules; }
 static string source,output,meshDir; static Material atlas,glass,emission;static Dictionary<string,Mesh> cache;
 [MenuItem("Tools/AYUTTHAYA/Shophouse V2/1 Create Clay Prefab")]
 static void Clay(){Run(true,false);}
 [MenuItem("Tools/AYUTTHAYA/Shophouse V2/2 Create PBR Prefabs")]
 static void Pbr(){Run(false,false);}
 [MenuItem("Tools/AYUTTHAYA/Shophouse V2/3 Create Playable Demo Scene")]
