 static string Source(){if(File.Exists(Root+"/Manifest.json"))return Root;foreach(var id in AssetDatabase.FindAssets("AV2Generator t:MonoScript")){var p=AssetDatabase.GUIDToAssetPath(id);if(Path.GetFileName(p)!="AV2Generator.cs")continue;var r=Path.GetDirectoryName(Path.GetDirectoryName(p)).Replace('\\','/');if(File.Exists(r+"/Manifest.json"))return r;}throw new IOException("Copy the complete AyutthayaShophouseV2 folder into Assets (including MeshData and Textures).");}
 static string Folder(string p,string n){string path=p+"/"+n;if(!AssetDatabase.IsValidFolder(path)){var id=AssetDatabase.CreateFolder(p,n);if(string.IsNullOrEmpty(id)||!AssetDatabase.IsValidFolder(path))throw new IOException("Could not create "+path);}return path;}
 static T Save<T>(T obj,string path) where T:Object{AssetDatabase.CreateAsset(obj,path);var saved=AssetDatabase.LoadAssetAtPath<T>(path);if(!saved)throw new IOException("Failed to save "+path);return saved;}
 static Vector3 V(float[] v){if(v==null||v.Length!=3)throw new InvalidDataException("Invalid position");return new Vector3(v[0],v[1],v[2]);}
 static Texture2D Texture(string name){string path=source+"/Textures/"+name+".png";var i=AssetImporter.GetAtPath(path) as TextureImporter;if(!i)throw new IOException("Missing texture: "+path);
  i.textureType=name=="Normal"?TextureImporterType.NormalMap:TextureImporterType.Default;i.sRGBTexture=name=="BaseColor"||name=="Emissive";i.maxTextureSize=4096;i.mipmapEnabled=true;i.wrapMode=TextureWrapMode.Clamp;i.anisoLevel=8;i.textureCompression=TextureImporterCompression.CompressedHQ;i.alphaSource=name=="MetallicSmoothness"?TextureImporterAlphaSource.FromInput:TextureImporterAlphaSource.None;i.alphaIsTransparency=false;i.SaveAndReimport();var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(!t)throw new IOException(path);return t;}
 static void ColorOf(Material m,Color c){if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(m.HasProperty("_Color"))m.SetColor("_Color",c);}
 static void Float(Material m,string p,float v){if(m.HasProperty(p))m.SetFloat(p,v);}
 static void Tex(Material m,string p,Texture t){if(m.HasProperty(p))m.SetTexture(p,t);}
 static void Materials(string dir,bool clay){bool srp=GraphicsSettings.currentRenderPipeline!=null;if(srp&&!GraphicsSettings.currentRenderPipeline.GetType().Name.Contains("Universal"))throw new InvalidOperationException("Use URP or Built-in Render Pipeline.");var shader=Shader.Find(srp?"Universal Render Pipeline/Lit":"Standard");if(!shader)throw new InvalidOperationException("This package supports URP and Built-in only (not HDRP).");
  atlas=new Material(shader){name="Shophouse_Atlas",enableInstancing=true};ColorOf(atlas,clay?new Color(.68f,.68f,.68f):Color.white);Float(atlas,"_Metallic",0);Float(atlas,"_Smoothness",.25f);Float(atlas,"_Glossiness",.25f);
  if(!clay){var albedo=Texture("BaseColor");Tex(atlas,"_BaseMap",albedo);Tex(atlas,"_MainTex",albedo);Tex(atlas,"_BumpMap",Texture("Normal"));atlas.EnableKeyword("_NORMALMAP");Float(atlas,"_BumpScale",.65f);Tex(atlas,"_MetallicGlossMap",Texture("MetallicSmoothness"));atlas.EnableKeyword(srp?"_METALLICSPECGLOSSMAP":"_METALLICGLOSSMAP");Float(atlas,"_WorkflowMode",1);Float(atlas,"_Metallic",1);Float(atlas,"_Smoothness",1);Float(atlas,"_GlossMapScale",1);Float(atlas,"_SmoothnessTextureChannel",0);atlas.DisableKeyword("_SMOOTHNESS_TEXTURE_ALBEDO_CHANNEL_A");Tex(atlas,"_OcclusionMap",Texture("AO"));atlas.EnableKeyword("_OCCLUSIONMAP");Float(atlas,"_OcclusionStrength",1);}
  atlas=Save(atlas,dir+"/Atlas.mat");glass=new Material(shader){name="Glass"};ColorOf(glass,clay?new Color(.68f,.68f,.68f):new Color(.26f,.43f,.50f,.27f));Float(glass,"_Metallic",0);Float(glass,"_Glossiness",.88f);Float(glass,"_Smoothness",.88f);
  if(!clay){if(srp){Float(glass,"_Surface",1);Float(glass,"_Blend",0);Float(glass,"_AlphaClip",0);glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.DisableKeyword("_ALPHAPREMULTIPLY_ON");}else{Float(glass,"_Mode",2);glass.EnableKeyword("_ALPHABLEND_ON");glass.DisableKeyword("_ALPHATEST_ON");glass.DisableKeyword("_ALPHAPREMULTIPLY_ON");}glass.SetOverrideTag("RenderType","Transparent");Float(glass,"_SrcBlend",(float)BlendMode.SrcAlpha);Float(glass,"_DstBlend",(float)BlendMode.OneMinusSrcAlpha);Float(glass,"_SrcBlendAlpha",(float)BlendMode.One);Float(glass,"_DstBlendAlpha",(float)BlendMode.OneMinusSrcAlpha);Float(glass,"_ZWrite",0);glass.SetShaderPassEnabled("ShadowCaster",false);glass.renderQueue=(int)RenderQueue.Transparent;}
  glass=Save(glass,dir+"/Glass.mat");emission=new Material(shader){name="Fluorescent"};ColorOf(emission,Color.white);if(!clay){Tex(emission,"_EmissionMap",Texture("Emissive"));emission.SetColor("_EmissionColor",new Color(1,.94f,.8f)*2);emission.EnableKeyword("_EMISSION");}emission=Save(emission,dir+"/Lamp.mat");
 }
 static Mesh Read(string name){if(cache.TryGetValue(name,out var old))return old;string path=source+"/MeshData/"+name+".bytes";using(var f=File.OpenRead(path))using(var r=new BinaryReader(f)){
  if(new string(r.ReadChars(4))!="AYV2")throw new InvalidDataException(path);int nv=r.ReadInt32(),ni=r.ReadInt32();if(nv<3||nv>2000000||ni<3||ni%3!=0||ni>12000000||f.Length!=12L+32L*nv+4L*ni)throw new InvalidDataException("Invalid size "+path);
  var v=new Vector3[nv];var n=new Vector3[nv];var uv=new Vector2[nv];var t=new int[ni];for(int i=0;i<nv;i++)v[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());for(int i=0;i<nv;i++)n[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());for(int i=0;i<nv;i++)uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());for(int i=0;i<ni;i++){t[i]=r.ReadInt32();if(t[i]<0||t[i]>=nv)throw new InvalidDataException("Bad index "+path);}var mesh=new Mesh{name=name,indexFormat=nv>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.vertices=v;mesh.normals=n;mesh.uv=uv;mesh.triangles=t;mesh.RecalculateBounds();mesh.RecalculateTangents();cache[name]=Save(mesh,meshDir+"/"+name+".asset");return cache[name];}}
 static GameObject MeshObject(string name,Transform parent,Mesh m,Material mat,string collision){var go=new GameObject(name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=m;if(mat)go.AddComponent<MeshRenderer>().sharedMaterial=mat;if(collision=="box"){var c=go.AddComponent<BoxCollider>();c.center=m.bounds.center;c.size=m.bounds.size;}else if(collision=="mesh")go.AddComponent<MeshCollider>().sharedMesh=m;return go;}
 static GameObject Build(Manifest manifest,bool clay){var root=new GameObject("Shophouse_V2");var building=root.AddComponent<AV2Building>();var modules=new List<AV2Module>();var doorRoot=new GameObject("DoubleEntrance");doorRoot.transform.SetParent(root.transform,false);var door=doorRoot.AddComponent<AV2Door>();var leaves=new List<Transform>();var angles=new List<float>();
  foreach(var e in manifest.modules){var mat=e.kind=="invisible"?null:(e.kind=="glass"||e.kind=="glassbreak")?glass:e.kind=="lamp"?emission:atlas;var obj=MeshObject(e.name,e.kind=="door"?doorRoot.transform:root.transform,Read(e.name),mat,e.collider);obj.transform.localPosition=V(e.pos);obj.transform.localRotation=Quaternion.Euler(0,e.rotation,0);var mod=obj.AddComponent<AV2Module>();mod.kind=e.kind;mod.level=e.group;modules.Add(mod);
   if(e.kind=="door"){var pane=MeshObject(e.glass,obj.transform,Read(e.glass),glass,"none");var box=obj.GetComponent<BoxCollider>();if(box){var bounds=obj.GetComponent<MeshFilter>().sharedMesh.bounds;bounds.Encapsulate(pane.GetComponent<MeshFilter>().sharedMesh.bounds);box.center=bounds.center;box.size=bounds.size;}leaves.Add(obj.transform);angles.Add(e.angle);}
   if(e.name.StartsWith("Furniture")||e.name.StartsWith("LightFixtures")||e.name=="AirConditioners"||e.name=="PottedPlants"||e.name=="Awnings"){var renderer=obj.GetComponent<Renderer>();if(renderer){var lod=obj.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.018f,new[]{renderer})});lod.RecalculateBounds();}}
   if(e.kind=="shutter"){var d=obj.AddComponent<AV2Door>();d.shutter=true;d.leaves=new[]{obj.transform};d.angles=new[]{0f};}
   if(e.kind=="break"||e.kind=="glassbreak"){var b=obj.AddComponent<AV2Breakable>();b.health=e.hp;b.level=e.group;b.support=e.support;b.building=building;var fragments=new List<GameObject>();foreach(var fr in e.fragments){var piece=MeshObject(fr.name,obj.transform,Read(fr.name),e.kind=="glassbreak"?glass:atlas,"none");piece.transform.localPosition=V(fr.pos);var mc=piece.AddComponent<MeshCollider>();mc.sharedMesh=piece.GetComponent<MeshFilter>().sharedMesh;mc.convex=true;var rb=piece.AddComponent<Rigidbody>();rb.isKinematic=true;rb.mass=e.kind=="glassbreak"?.2f:1.8f;piece.SetActive(false);fragments.Add(piece);}b.fragments=fragments.ToArray();}
  }door.leaves=leaves.ToArray();door.angles=angles.ToArray();building.modules=modules.ToArray();
  // Lighting stays separate from the structural mesh; actual point lights for walkable rooms.
  if(!clay)for(int floor=0;floor<3;floor++)for(int j=0;j<2;j++){var go=new GameObject("InteriorLight_"+floor+"_"+j);go.transform.SetParent(root.transform,false);go.transform.localPosition=new Vector3(0,floor*3.3f+2.82f,4+j*7);var light=go.AddComponent<Light>();light.type=LightType.Point;light.color=new Color(1,.95f,.85f);light.range=8;light.intensity=2.1f;light.shadows=LightShadows.None;var m=go.AddComponent<AV2Module>();m.kind="lamp";m.level=floor;modules.Add(m);}building.modules=modules.ToArray();return root;
 }
 static GameObject AvatarPart(PrimitiveType type,Transform parent,string name,Vector3 pos,Vector3 scale,Material m){var g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=pos;g.transform.localScale=scale;Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=m;return g;}
 static GameObject Player(string dir){var p=new GameObject("Somchai_DemoPlayer");var cc=p.AddComponent<CharacterController>();cc.height=1.72f;cc.radius=.28f;cc.center=new Vector3(0,.86f,0);cc.stepOffset=.28f;cc.slopeLimit=50;cc.skinWidth=.035f;var cam=new GameObject("PlayerCamera");cam.transform.SetParent(p.transform,false);var camera=cam.AddComponent<Camera>();camera.nearClipPlane=.05f;camera.fieldOfView=65;cam.AddComponent<AudioListener>();cam.tag="MainCamera";var avatar=new GameObject("PlaceholderAvatar");avatar.transform.SetParent(p.transform,false);var shader=atlas.shader;var shirt=new Material(shader);ColorOf(shirt,new Color(.13f,.27f,.36f));shirt=Save(shirt,dir+"/AvatarShirt.mat");var skin=new Material(shader);ColorOf(skin,new Color(.62f,.43f,.29f));skin=Save(skin,dir+"/AvatarSkin.mat");var pants=new Material(shader);ColorOf(pants,new Color(.15f,.15f,.17f));pants=Save(pants,dir+"/AvatarPants.mat");AvatarPart(PrimitiveType.Capsule,avatar.transform,"Torso",new Vector3(0,1.08f,0),new Vector3(.44f,.34f,.28f),shirt);AvatarPart(PrimitiveType.Sphere,avatar.transform,"Head",new Vector3(0,1.57f,0),new Vector3(.25f,.28f,.24f),skin);foreach(int s in new[]{-1,1}){AvatarPart(PrimitiveType.Capsule,avatar.transform,"Leg",new Vector3(s*.13f,.43f,0),new Vector3(.19f,.37f,.2f),pants);AvatarPart(PrimitiveType.Capsule,avatar.transform,"Arm",new Vector3(s*.28f,1.0f,0),new Vector3(.13f,.28f,.13f),shirt);}var player=p.AddComponent<AV2Player>();player.view=camera;player.avatar=avatar;return p;}
 static void Run(bool clay,bool demo){GameObject building=null,player=null;string dest=null;try{if(demo&&!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())return;AssetDatabase.Refresh();source=Source();var manifest=JsonUtility.FromJson<Manifest>(File.ReadAllText(source+"/Manifest.json"));if(manifest==null||manifest.modules==null||manifest.modules.Length==0)throw new InvalidDataException("Invalid manifest");string baseFolder=Folder("Assets","GeneratedAyutthayaShophouseV2");string unique=AssetDatabase.GenerateUniqueAssetPath(baseFolder+(clay?"/Clay":"/PBR"));output=dest=Folder(baseFolder,Path.GetFileName(unique));meshDir=Folder(output,"Meshes");string matDir=Folder(output,"Materials"),prefabDir=Folder(output,"Prefabs");cache=new Dictionary<string,Mesh>();Materials(matDir,clay);building=Build(manifest,clay);string buildingPath=prefabDir+"/ShophouseV2.prefab";var bp=PrefabUtility.SaveAsPrefabAsset(building,buildingPath);if(!bp)throw new IOException("Building prefab save failed");Object.DestroyImmediate(building);building=null;
  if(!clay){player=Player(matDir);var pp=PrefabUtility.SaveAsPrefabAsset(player,prefabDir+"/Somchai_DemoPlayer.prefab");if(!pp)throw new IOException("Player prefab save failed");Object.DestroyImmediate(player);player=null;}
  AssetDatabase.SaveAssets();if(demo){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);building=(GameObject)PrefabUtility.InstantiatePrefab(bp);var pp=AssetDatabase.LoadAssetAtPath<GameObject>(prefabDir+"/Somchai_DemoPlayer.prefab");player=(GameObject)PrefabUtility.InstantiatePrefab(pp);player.transform.position=new Vector3(0,.05f,-2.6f);player.GetComponent<AV2Player>().testBuilding=building.GetComponent<AV2Building>();var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.name="DemoGround";ground.transform.position=new Vector3(0,-.36f,5);ground.transform.localScale=new Vector3(40,.18f,40);var gm=new Material(atlas.shader);ColorOf(gm,new Color(.33f,.35f,.36f));ground.GetComponent<MeshRenderer>().sharedMaterial=Save(gm,matDir+"/DemoGround.mat");var sun=new GameObject("Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.25f;sun.shadows=LightShadows.Soft;sun.transform.rotation=Quaternion.Euler(45,-30,0);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.48f,.49f,.52f);if(!EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene(),output+"/PlayableDemo.unity"))throw new IOException("Scene save failed");Selection.activeGameObject=building;}
  else {Selection.activeObject=bp;EditorGUIUtility.PingObject(bp);}File.WriteAllText(output+"/GenerationReport.txt","Modules: "+manifest.modules.Length+"\nMesh assets (including inactive fracture fragments): "+cache.Count+"\nTriangles (all saved mesh assets): "+cache.Values.Sum(m=>(long)m.GetIndexCount(0)/3)+"\nUnity editor generation completed. Runtime test still required.\n");AssetDatabase.Refresh();Debug.Log("Shophouse V2 generated: "+output);
 }catch(Exception ex){if(building)Object.DestroyImmediate(building);if(player)Object.DestroyImmediate(player);Debug.LogException(ex);EditorUtility.DisplayDialog("Shophouse V2",ex.Message+"\nPartial output (if any): "+dest,"OK");}}
